import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import { mockPrizes } from '../../../data/mockData';
import styles from './MyRedemptionsPage.module.css';

const MyRedemptionsPage = () => {
  // Dados mocados para os resgates do usuário
  const redemptions = [
    { id: 1, prizeName: mockPrizes[0].name, date: '01/08/2025' },
  ];

  return (
    <ContentWrapper title="Meus Resgates">
      <ul className={styles.list}>
        {redemptions.map(item => (
          <li key={item.id} className={styles.listItem}>
            <span className={styles.prizeName}>{item.prizeName}</span>
            <span className={styles.date}>Resgatado em {item.date}</span>
          </li>
        ))}
      </ul>
    </ContentWrapper>
  );
};

export default MyRedemptionsPage;
